/**
 * API token lifecycle endpoints (D30).
 *
 * This file deliberately has **no create endpoint**. The secret is generated by
 * the operator's local CLI (`npm run token -- create`), which prints it exactly
 * once; no HTTP response ever carries a credential, and an admin compromised over
 * the wire cannot mint a token whose secret it does not already hold. Listing and
 * retirement stay on the API because they are decisions an admin should be able to
 * make remotely, and both are audited.
 *
 * Both routes are `admin`-only (see `requiredRole`), which is stricter than the
 * default "reads need viewer": the token list names the credentials that can act.
 */

import { FastifyInstance } from 'fastify';
import { getDb } from '../db/index.js';
import { recordAudit } from '../security/audit.js';
import { countTokens, listTokens, retireToken, tokenState } from '../security/tokens.js';

export async function tokenRoutes(app: FastifyInstance) {
  app.get('/api/tokens', async (_request: any, reply: any) => {
    const db = getDb();
    const tokens = listTokens(db);
    return reply.send({
      count: tokens.length,
      live: tokens.filter((token) => token.state === 'live').length,
      // No secret and no hash: id, role, prefix, timestamps and state only.
      tokens,
    });
  });

  app.post('/api/tokens/:id/retire', async (request: any, reply: any) => {
    const db = getDb();
    const id = String(request.params?.id ?? '');
    const body = (request.body ?? {}) as Record<string, unknown>;
    const reason =
      typeof body.reason === 'string' && body.reason.trim()
        ? body.reason.trim().slice(0, 200)
        : 'retired via API';
    const actor = request.hatcheryActor ?? {
      name: 'anonymous',
      role: 'anonymous',
      authenticated: false,
    };

    const result = retireToken(db, id, reason);
    if (!result.token) {
      return reply.code(404).send({ error: 'Unknown token id' });
    }

    // The lifecycle action gets its own row, beside the request row the response
    // hook writes. Neither contains the token's secret, which the server never has.
    recordAudit(db, {
      actor: actor.name,
      role: actor.role,
      authenticated: actor.authenticated,
      method: request.method,
      path: `/api/tokens/${id}/retire`,
      statusCode: 200,
      action: 'token.retired',
      detail: `${result.changed ? 'retired' : 'already retired'} token ${id} (${reason})`,
    });

    return reply.send({
      id: result.token.id,
      changed: result.changed,
      revoked_at: result.token.revoked_at,
      retired_reason: result.token.retired_reason,
      state: tokenState(result.token),
      counts: countTokens(db),
    });
  });
}
